  function cFields(r){return [['原币金额',r.hidden?'••••':r.amount],...(r.converted?[['历史折算',r.hidden?'••••':r.converted]]:[]),['分类',r._parentCategory&&r.categoryLabel&&r._parentCategory!==r.categoryLabel?r._parentCategory+' / '+r.categoryLabel:r.categoryLabel||r.title],['账户',r.accountName||'未设置'],['账本',r._ledgerName||r.ledgerName||state.ledger],['备注',r._rawNote===undefined?r.note||r.title:r._rawNote||'未填写'],['时间',(r.happenedAt||'').replace('T',' ')],['标签',r.tags.map(t=>typeof t==='string'?t:t.label).join(' · ')||'未添加'],['附件',String(r.attachments||0)+'张'],['统计规则',(r.status||[]).join(' · ')||'正常计入'],['访问状态',r.readOnly?'只读':'可编辑']];}
